mapper.delete:
DELETE FROM administrator_password_setup_workflows
WHERE actor_identity_id = #{actorIdentityId}
  AND idempotency_key = #{idempotencyKey}
  AND expires_at <= #{now}

mapper.select:
SELECT *
FROM administrator_password_setup_workflows
WHERE actor_identity_id = #{actorIdentityId} AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE administrator_password_setup_workflows
SET next_attempt_at = #{retryAt}, lease_owner = NULL, lease_until = NULL,
    recovery_exhausted_at = NULL, last_failure = #{lastFailure}
WHERE workflow_id = #{workflowId} AND outcome_code IS NULL
  AND lease_owner = #{claimant} AND attempt_count = #{attemptCount}

UPDATE administrator_password_setup_workflows
SET next_attempt_at = #{exhaustedAt}, lease_owner = NULL, lease_until = NULL,
    recovery_exhausted_at = #{exhaustedAt}, last_failure = #{lastFailure}
WHERE workflow_id = #{workflowId} AND outcome_code IS NULL
  AND lease_owner = #{claimant} AND attempt_count = #{attemptCount}
